select public.importa_quiz('javascript', $j$[
  {"livello":"L1","testo":"Quale metodo converte una stringa in un numero intero?","spiegazione":"parseInt analizza la stringa e restituisce un intero; se non è valida restituisce NaN.","opzioni":["parseInt","Number.toString","Math.round","String.toInt"],"corretta":0},
  {"livello":"L1","testo":"Quale metodo aggiunge un elemento in fondo a un array?","spiegazione":"push muta l'array e restituisce la nuova lunghezza; concat crea un nuovo array.","opzioni":["push","pop","shift","slice"],"corretta":0},
  {"livello":"L1","testo":"Quale tipo rappresenta un valore vero o falso?","spiegazione":"boolean ha solo due valori: true e false.","opzioni":["boolean","number","string","symbol"],"corretta":0},
  {"livello":"L1","testo":"Quale operatore somma numeri e concatena stringhe?","spiegazione":"Il + è sovraccarico: con due numeri somma, con una stringa concatena.","opzioni":["+","-","*","%"],"corretta":0},
  {"livello":"L1","testo":"Quale metodo seleziona un elemento del DOM tramite id?","spiegazione":"getElementById restituisce il primo elemento con quell'id, oppure null.","opzioni":["document.getElementById","document.querySelectorAll","document.getElementsByClass","document.createTextNode"],"corretta":0},
  {"livello":"L1","testo":"Quale parola chiave dichiara una funzione?","spiegazione":"function introduce la dichiarazione; le arrow function usano const e =>.","opzioni":["function","def","fn","func"],"corretta":0},
  {"livello":"L1","testo":"Quale metodo trasforma un valore in stringa JSON?","spiegazione":"JSON.stringify serializza oggetti e array; JSON.parse fa l'operazione inversa.","opzioni":["JSON.stringify","JSON.parse","toString(JSON)","Object.entries"],"corretta":0},
  {"livello":"L1","testo":"Quale metodo esegue una funzione per ogni elemento di un array?","spiegazione":"forEach itera e non restituisce nulla; map invece restituisce un nuovo array.","opzioni":["forEach","map","filter","reduce"],"corretta":0},

  {"livello":"L2","testo":"Qual è la differenza di scope tra let e var?","spiegazione":"let è limitato al blocco, var alla funzione: questo evita sorprese nei cicli e nei blocchi.","opzioni":["let ha scope di blocco, var di funzione","var ha scope di blocco, let di funzione","Sono identici","let è globale e var locale"],"corretta":0},
  {"livello":"L2","testo":"Cosa distingue map da forEach?","spiegazione":"map restituisce un nuovo array con i valori trasformati, forEach no.","opzioni":["map restituisce un nuovo array, forEach no","forEach restituisce un nuovo array, map no","map muta l'array originale","forEach è deprecato"],"corretta":0},
  {"livello":"L2","testo":"Cosa restituisce typeof null?","spiegazione":"Restituisce object per un difetto storico del linguaggio: null va verificato con === null.","opzioni":["\"object\"","\"null\"","\"undefined\"","\"boolean\""],"corretta":0},
  {"livello":"L2","testo":"Cosa fa l'operatore ?? (nullish coalescing)?","spiegazione":"Usa il valore di destra solo se quello di sinistra è null o undefined, non per 0 o stringa vuota.","opzioni":["Applica il default solo per null o undefined","Applica il default per qualsiasi valore falsy","Confronta i tipi","Assegna una variabile"],"corretta":0},
  {"livello":"L2","testo":"Cosa fa l'operatore ?. (optional chaining)?","spiegazione":"Interrompe l'accesso restituendo undefined invece di lanciare errore su null o undefined.","opzioni":["Evita l'errore leggendo null o undefined","Crea una Promise","Converte in stringa","Rende la proprietà immutabile"],"corretta":0},
  {"livello":"L2","testo":"Cosa significa che gli oggetti sono passati per riferimento?","spiegazione":"La funzione riceve il riferimento: le modifiche all'oggetto sono visibili al chiamante.","opzioni":["Le modifiche all'oggetto sono visibili al chiamante","La funzione riceve una copia profonda","L'oggetto diventa immutabile","Il riferimento viene serializzato"],"corretta":0},
  {"livello":"L2","testo":"Cosa fa event.preventDefault()?","spiegazione":"Blocca il comportamento predefinito del browser, come l'invio del form o il click sul link.","opzioni":["Blocca il comportamento predefinito del browser","Ferma la propagazione agli antenati","Rimuove il listener","Annulla la Promise"],"corretta":0},

  {"livello":"L3","testo":"Perché una closure continua a vedere le variabili esterne?","spiegazione":"La funzione cattura l'ambiente lessicale in cui è stata creata, non solo i valori al momento della chiamata.","opzioni":["Perché cattura l'ambiente lessicale di creazione","Perché copia tutte le variabili globali","Perché usa il prototipo","Perché il garbage collector le conserva"],"corretta":0},
  {"livello":"L3","testo":"Perché this può perdersi in una callback passata come argomento?","spiegazione":"Il contesto dipende da come la funzione viene chiamata: con arrow function o bind si lega il valore voluto.","opzioni":["Perché il contesto dipende dalla chiamata: serve arrow o bind","Perché this non esiste in JavaScript","Perché le callback sono asincrone","Perché this vale sempre undefined"],"corretta":0},
  {"livello":"L3","testo":"Perché await si usa solo dentro una funzione async?","spiegazione":"await sospende l'esecuzione della funzione asincrona; fuori da un contesto async non è valido.","opzioni":["Perché sospende l'esecuzione di una funzione async","Perché è deprecato altrove","Perché richiede un web worker","Perché funziona solo nei browser"],"corretta":0},
  {"livello":"L3","testo":"Qual è la differenza tra microtask e macrotask?","spiegazione":"Le Promise finiscono nella coda dei microtask ed eseguono prima dei timer, che sono macrotask.","opzioni":["Le Promise eseguono prima dei timer","I timer eseguono prima delle Promise","Sono la stessa coda","I microtask sono sempre sincroni"],"corretta":0},
  {"livello":"L3","testo":"Perché JSON.parse può lanciare un'eccezione?","spiegazione":"Se la stringa non è JSON valido lancia SyntaxError: va protetto con try/catch.","opzioni":["Perché una stringa non valida lancia SyntaxError","Perché è asincrono","Perché richiede un callback","Perché converte solo numeri"],"corretta":0},
  {"livello":"L3","testo":"Come si confrontano due oggetti con ===?","spiegazione":"Confronta i riferimenti, non il contenuto: due oggetti uguali ma distinti risultano diversi.","opzioni":["Confronta i riferimenti, non il contenuto","Confronta tutte le proprietà","Confronta la stringa JSON","Lancia un errore"],"corretta":0},
  {"livello":"L3","testo":"Perché sort richiede attenzione sull'array originale?","spiegazione":"sort muta l'array: per non alterarlo si usa una copia con spread o slice.","opzioni":["Perché muta l'array originale","Perché restituisce sempre undefined","Perché funziona solo sui numeri","Perché è asincrono"],"corretta":0},

  {"livello":"L4","testo":"Perché un listener aggiunto a ogni render senza rimozione è un problema?","spiegazione":"I listener si accumulano, mantengono riferimenti e causano memory leak e callback duplicate.","opzioni":["Si accumulano e causano memory leak","Il browser li rimuove da solo","Rallentano solo il CSS","Impediscono il rendering"],"corretta":0},
  {"livello":"L4","testo":"Perché il debounce è utile su un campo di ricerca?","spiegazione":"Riduce le chiamate: esegue la ricerca solo dopo una pausa nella digitazione.","opzioni":["Riduce le chiamate eseguendo dopo una pausa","Aumenta la frequenza delle richieste","Blocca il thread principale","Evita il CORS"],"corretta":0},
  {"livello":"L4","testo":"Perché non si usa eval con input dell'utente?","spiegazione":"Esegue codice arbitrario nel contesto della pagina: è una porta aperta a code injection.","opzioni":["Esegue codice arbitrario e apre a code injection","È più lento di JSON.parse","Non supporta le stringhe","Rompe il garbage collector"],"corretta":0},
  {"livello":"L4","testo":"Perché il blocco del thread è critico anche in JavaScript?","spiegazione":"JavaScript gira su un thread: un calcolo lungo impedisce l'aggiornamento dell'interfaccia.","opzioni":["Perché un calcolo lungo blocca l'interfaccia","Perché JavaScript usa un thread per task","Perché il DOM è asincrono","Perché le Promise sono sincrone"],"corretta":0}
]$j$::jsonb);

select public.importa_quiz('react', $j$[
  {"livello":"L1","testo":"Quale hook gestisce uno stato locale nel componente?","spiegazione":"useState restituisce il valore corrente e la funzione per aggiornarlo.","opzioni":["useState","useEffect","useRef","useMemo"],"corretta":0},
  {"livello":"L1","testo":"Quale hook esegue effetti collaterali?","spiegazione":"useEffect sincronizza il componente con sistemi esterni: fetch, subscription, timer.","opzioni":["useEffect","useState","useContext","useReducer"],"corretta":0},
  {"livello":"L1","testo":"Come si passa un dato da un componente genitore a un figlio?","spiegazione":"Tramite props, lette come oggetto nel componente figlio.","opzioni":["Con le props","Con le variabili globali","Con localStorage","Con i CSS"],"corretta":0},
  {"livello":"L1","testo":"Quale attributo HTML diventa className in JSX?","spiegazione":"In JSX si usa className al posto di class, perché class è una parola riservata di JavaScript.","opzioni":["class","className","styleClass","cssClass"],"corretta":0},
  {"livello":"L1","testo":"Come si inserisce un'espressione JavaScript dentro JSX?","spiegazione":"Le graffe racchiudono espressioni, non istruzioni come if o for.","opzioni":["Con le graffe","Con le parentesi tonde","Con i doppi apici","Con il simbolo $"],"corretta":0},
  {"livello":"L1","testo":"Quale componente permette di restituire più figli senza un nodo aggiuntivo?","spiegazione":"Fragment, abbreviato con <>...</>, non produce markup nel DOM.","opzioni":["Fragment","Portal","StrictMode","Suspense"],"corretta":0},
  {"livello":"L1","testo":"Quale hook conserva un valore tra i render senza provocarne uno nuovo?","spiegazione":"useRef mantiene un riferimento mutabile e non innesca il re-render.","opzioni":["useRef","useState","useMemo","useEffect"],"corretta":0},
  {"livello":"L1","testo":"Come si gestisce un click in JSX?","spiegazione":"Si usa onClick con una funzione: onClick={gestisciClick}, non una stringa.","opzioni":["onClick={gestisciClick}","onclick=\"gestisciClick()\"","click={gestisciClick}","onClick=\"gestisciClick\""],"corretta":0},

  {"livello":"L2","testo":"Cosa fa la key in una lista React?","spiegazione":"Identifica un elemento tra i render: deve essere stabile e unica tra i fratelli.","opzioni":["Identifica l'elemento tra i render","Imposta lo stile dell'elemento","Definisce l'ordine alfabetico","Crea un id HTML"],"corretta":0},
  {"livello":"L2","testo":"Cosa restituisce useState?","spiegazione":"Una coppia: valore corrente e funzione setter che richiede un nuovo render.","opzioni":["Il valore e la funzione per aggiornarlo","Solo il valore","Solo il setter","Un oggetto con get e set"],"corretta":0},
  {"livello":"L2","testo":"Quando è necessario usare la forma a funzione nel setter di useState?","spiegazione":"Quando il nuovo valore dipende dallo stato precedente: evita aggiornamenti persi.","opzioni":["Quando il nuovo valore dipende dallo stato precedente","Mai, è equivalente","Solo con oggetti annidati","Solo negli eventi"],"corretta":0},
  {"livello":"L2","testo":"Cosa fa useEffect con un array di dipendenze vuoto?","spiegazione":"Esegue l'effetto una volta dopo il primo render, con cleanup allo smontaggio.","opzioni":["Esegue l'effetto solo dopo il primo render","Esegue a ogni render","Non esegue mai","Esegue solo al click"],"corretta":0},
  {"livello":"L2","testo":"Cosa fa useContext?","spiegazione":"Legge il valore del context più vicino, evitando di passare props a ogni livello.","opzioni":["Legge il valore del context più vicino","Crea un nuovo context","Esegue un effetto","Memorizza un calcolo"],"corretta":0},
  {"livello":"L2","testo":"Come si applica uno stile inline in JSX?","spiegazione":"style accetta un oggetto con proprietà camelCase: style={{ color: 'red' }}.","opzioni":["Con un oggetto e proprietà camelCase","Con una stringa CSS completa","Solo con className","Con il tag style nel body"],"corretta":0},
  {"livello":"L2","testo":"Cosa rende controllato un campo di input?","spiegazione":"Il valore deriva dallo stato (value) e le modifiche passano da onChange.","opzioni":["value collegato allo stato e onChange che lo aggiorna","Un ref al DOM","L'attributo required","Il type corretto"],"corretta":0},
  {"livello":"L2","testo":"Cosa fa useMemo?","spiegazione":"Memorizza il risultato di un calcolo e lo ricalcola solo quando cambiano le dipendenze.","opzioni":["Memorizza un calcolo tra i render","Memorizza un componente","Crea un effetto","Crea un ref"],"corretta":0},

  {"livello":"L3","testo":"Cosa significa che React è dichiarativo?","spiegazione":"Descrivi l'interfaccia in funzione dello stato: React calcola le modifiche al DOM necessarie.","opzioni":["L'interfaccia è descritta in funzione dello stato","Bisogna aggiornare il DOM a mano","Il rendering avviene sul server","Lo stato è globale"],"corretta":0},
  {"livello":"L3","testo":"Perché non si chiamano hook dentro if o cicli?","spiegazione":"Gli hook devono essere chiamati nello stesso ordine a ogni render, altrimenti lo stato si disallinea.","opzioni":["Perché l'ordine delle chiamate deve restare stabile","Perché i cicli non supportano gli hook","Perché aumenta la memoria","Perché il lint lo impedisce e basta"],"corretta":0},
  {"livello":"L3","testo":"Perché una subscription in useEffect richiede cleanup?","spiegazione":"Senza cleanup si accumulano listener e si aggiorna uno stato non più montato.","opzioni":["Per evitare listener accumulati e aggiornamenti su componenti smontati","Per velocizzare il primo render","Per evitare il CSS","Per chiudere il browser"],"corretta":0},
  {"livello":"L3","testo":"Perché si solleva lo stato al componente genitore?","spiegazione":"Due componenti fratelli devono condividere lo stesso dato: il genitore diventa la fonte di verità.","opzioni":["Per condividere lo stato tra fratelli","Per ridurre le props","Per migliorare il CSS","Per evitare gli hook"],"corretta":0},
  {"livello":"L3","testo":"Cosa può causare un loop infinito in useEffect?","spiegazione":"Un setState nell'effetto con una dipendenza che cambia a ogni render innesca render continui.","opzioni":["Un setState con una dipendenza instabile","Un array di dipendenze vuoto","Un cleanup mancante","Un useRef"],"corretta":0},
  {"livello":"L3","testo":"Perché la key non deve cambiare a ogni render?","spiegazione":"Cambiando key React smonta e rimonta il nodo, perdendo stato, focus e prestazioni.","opzioni":["React rimonta il nodo perdendo stato e focus","React ignora la lista","La lista non si aggiorna","Cambia l'ordine alfabetico"],"corretta":0},
  {"livello":"L3","testo":"Cosa fa React.memo su un componente?","spiegazione":"Salta il re-render se le props sono uguali per confronto superficiale.","opzioni":["Salta il re-render se le props non cambiano","Memorizza lo stato","Crea un context","Esegue un effetto"],"corretta":0},

  {"livello":"L4","testo":"Perché è sconsigliato copiare le props nello stato con useEffect?","spiegazione":"Crea due fonti di verità che possono desincronizzarsi: meglio derivare il valore durante il render.","opzioni":["Crea due fonti di verità che si desincronizzano","React non supporta le props","Rallenta il bundler","Impedisce il cleanup"],"corretta":0},
  {"livello":"L4","testo":"A cosa servono React.lazy e Suspense?","spiegazione":"Caricano un componente solo quando serve (code splitting) mostrando un fallback durante l'attesa.","opzioni":["A caricare componenti su richiesta con un fallback","A memorizzare lo stato globale","A gestire gli errori di rete","A ottimizzare le immagini"],"corretta":0},
  {"livello":"L4","testo":"Perché gli aggiornamenti di stato sono raggruppati?","spiegazione":"Il batching riduce i render: più setState nello stesso evento producono un solo aggiornamento.","opzioni":["Per ridurre il numero di render","Per garantire l'ordine alfabetico","Per sincronizzare il server","Per evitare le Promise"],"corretta":0},
  {"livello":"L4","testo":"Perché un errore in render richiede un error boundary?","spiegazione":"Senza boundary React smonta l'albero e resta una pagina bianca; il boundary mostra un fallback.","opzioni":["Senza boundary l'albero viene smontato e la pagina resta bianca","Perché gli errori sono asincroni","Perché il CSS si rompe","Perché lo stato diventa immutabile"],"corretta":0}
]$j$::jsonb);
